def frequencySort(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    sorted_chars = sorted(counts.keys(), key=lambda ch: (-counts[ch], ch))
    return ''.join(ch * counts[ch] for ch in sorted_chars)

